/**
 * Generate mock CSV files for a Ukrainian tech repair workshop.
 *
 * File types (matching TaskFileRole enum):
 *   - jobs.csv      — Repair job tickets
 *   - clients.csv   — Customer directory
 *   - parts.csv     — Spare parts catalog
 *   - devices.csv   — Device catalog
 *
 * Usage: npx tsx tests/fixtures/generate-mock-data.ts
 */

import { mkdir, writeFile } from 'fs/promises';
import { join } from 'path';

const OUTPUT_DIR = join(__dirname, 'mock-data');

// ──────────────────────────────────────────────
// CSV Helpers
// ──────────────────────────────────────────────

function csvField(value: string | number | null | undefined): string {
  const str = value == null ? '' : String(value);
  if (str.includes(',') || str.includes('"') || str.includes('\n') || str.includes('\r')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

function csvRow(fields: (string | number | null | undefined)[]): string {
  return fields.map(csvField).join(',');
}

function csvFile(headers: string[], rows: (string | number | null | undefined)[][]): string {
  return [csvRow(headers), ...rows.map(csvRow)].join('\n') + '\n';
}

